  chat_id: $json.chat_id\n}) }}", "options": {}}, "id": "node-call-image-edit-api", "name": "Call Image Edit API", "type": "n8n-nodes-base.httpRequest", "position": [640, 320], "typeVersion": 4.2}, {"parameters": {"resource": "file", "operation": "get", "fileId": "={{ $(''Telegram Trigger'').first().json.message?.photo ? $(''Telegram Trigger'').first().json.message.photo.slice(-1)[0].file_id : $(''Telegram Trigger'').first().json.message?.document?.file_id }}"}, "id": "download-tg-photo-node", "name": "Download Telegram Photo", "type": "n8n-nodes-base.telegram", "typeVersion": 1.2, "position": [140, 272], "credentials": {"telegramApi": {"id": "ASiKmvQz4bYnK32G", "name": "Telegram account"}}}, {"parameters": {"jsCode": "const triggerJson = $(''Telegram Trigger'').first()?.json || $input.first()?.json || $json || {};\nconst message = triggerJson.message || triggerJson.callback_query?.message;\nconst fromUser = triggerJson.message?.from || triggerJson.callback_query?.from;\n\nconst userId = fromUser?.id != null ? String(fromUser.id).trim() : '''';\nconst chatId = message?.chat?.id != null ? String(message.chat.id).trim() : (userId || '''');\nconst username = fromUser?.username ? `@${fromUser.username}` : '''';\nconst fullName = [fromUser?.first_name, fromUser?.last_name].filter(Boolean).join('' '') || username || ''\u0421\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a'';\n\nlet allowedRaw = '''';\ntry {\n  if (typeof $env !== ''undefined'' && $env.ALLOWED_TELEGRAM_IDS) {\n    allowedRaw = String($env.ALLOWED_TELEGRAM_IDS);\n  } else if (typeof process !== ''undefined'' && process.env && process.env.ALLOWED_TELEGRAM_IDS) {\n    allowedRaw = String(process.env.ALLOWED_TELEGRAM_IDS);\n  }\n} catch (e) {\n  allowedRaw = '''';\n}\n\nallowedRaw = allowedRaw.trim();\nconst allowedList = allowedRaw\n  ? allowedRaw.split(/[\\s,;]+/).map(s => s.trim()).filter(Boolean)\n  : [];\n\n// \u0415\u0441\u043b\u0438 \u0441\u043f\u0438\u0441\u043e\u043a \u043f\u0443\u0441\u0442 \u2014 \u0440\u0435\u0436\u0438\u043c \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 (\u0434\u043e\u0441\u0442\u0443\u043f \u043e\u0442\u043a\u0440\u044b\u0442)\n// \u0415\u0441\u043b\u0438 \u0441\u043f\u0438\u0441\u043e\u043a \u0437\u0430\u043f\u043e\u043b\u043d\u0435\u043d \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c userId \u0438\u043b\u0438 chatId\nconst isAllowed = (allowedList.length === 0) ||\n  (userId && allowedList.includes(userId)) ||\n  (chatId && allowedList.includes(chatId));\n\nreturn [{\n  json: {\n    ...triggerJson,\n    auth: {\n      user_id: userId,\n      chat_id: chatId,\n      user_name: fullName,\n      username: username,\n      is_allowed: isAllowed,\n      whitelist_configured: allowedList.length > 0,\n      checked_at: new Date().toISOString()\n    }\n  }\n}];"}, "id": "node-check-manager-whitelist", "name": "Check Manager Whitelist", "type": "n8n-nodes-base.code", "typeVersion": 2, "position": [-780, 208]}, {"parameters": {"conditions": {"options": {"caseSensitive": true, "leftValue": "", "typeValidation": "strict", "version": 2}, "conditions": [{"operator": {"operation": "equals", "type": "boolean"}, "rightValue": true, "id": "cond-is-allowed", "leftValue": "={{ $json.auth ? $json.auth.is_allowed : true }}"}], "combinator": "and"}, "options": {}}, "id": "node-is-user-allowed", "name": "Is User Allowed?", "type": "n8n-nodes-base.if", "position": [-680, 208], "typeVersion": 2}, {"parameters": {"chatId": "={{ $(''Check Manager Whitelist'').first()?.json?.auth?.chat_id || $json.auth?.chat_id || $(''Telegram Trigger'').first()?.json?.message?.chat?.id }}", "text": "\u26d4\ufe0f *\u0414\u043e\u0441\u0442\u0443\u043f \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d (Manager-Only Mode)*\n\n\u042d\u0442\u043e\u0442 \u0431\u043e\u0442 \u043f\u0440\u0435\u0434\u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d \u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0434\u043b\u044f \u0430\u0432\u0442\u0