system_code || ''H1'',\n  color: parsed.color || ''white'',\n  count: 1\n}];\n\nconst colorLabels = {\n  white: ''\u0411\u0435\u043b\u044b\u0439'',\n  black: ''\u0427\u0435\u0440\u043d\u044b\u0439'',\n  stainless_steel: ''\u041d\u0435\u0440\u0436\u0430\u0432\u0435\u044e\u0449\u0430\u044f \u0441\u0442\u0430\u043b\u044c'',\n  none: ''\u0421\u0442\u0430\u043d\u0434\u0430\u0440\u0442''\n};\nconst colorRu = colorLabels[parsed.color] || parsed.color || ''\u0411\u0435\u043b\u044b\u0439'';\n\nreturn [{\n  json: {\n    action: parsed.action || ''select_dispenser'',\n    sku: sku,\n    name: parsed.name || items[0].name || `\u0414\u0438\u0441\u043f\u0435\u043d\u0441\u0435\u0440 Tork (\u0430\u0440\u0442. ${sku})`,\n    system_code: parsed.system_code || items[0].system_code || ''H1'',\n    color: parsed.color || items[0].color || ''white'',\n    color_ru: colorRu,\n    category: parsed.category || ''dispenser'',\n    price: parsed.price || 0,\n    items: items,\n    items_count: items.length,\n    tg_user_id: tgUserId,\n    chat_id: trigger.message?.chat?.id || tgUserId,\n    raw_payload: parsed\n  }\n}];"}, "id": "node-parse-selected-dispenser", "name": "Parse Selected Dispenser", "type": "n8n-nodes-base.code", "position": [0, 100], "typeVersion": 2}, {"parameters": {"operation": "executeQuery", "query": "UPDATE user_sessions_leads SET selected_sku = ''{{ $json.sku }}'', selected_bundle = ''{{ JSON.stringify($json.items || $json.raw_payload) }}''::jsonb, updated_at = NOW() WHERE tg_user_id = {{ $json.tg_user_id }} RETURNING *;", "options": {}}, "id": "node-save-selected-dispenser", "name": "Save Selected Dispenser (SQL)", "type": "n8n-nodes-base.postgres", "position": [200, 100], "typeVersion": 2.4, "credentials": {"postgres": {"id": "ssRaEX0w25vYf2wI", "name": "Postgres account"}}}, {"parameters": {"chatId": "={{ $(''Parse Selected Dispenser'').first().json.chat_id || $(''Parse Selected Dispenser'').first().json.tg_user_id || $(''Telegram Trigger'').first()?.json?.message?.chat?.id }}", "text": "={{ ''\u2705 <b>\u0412\u044b\u0431\u0440\u0430\u043d \u0434\u0438\u0441\u043f\u0435\u043d\u0441\u0435\u0440 \u0434\u043b\u044f \u043f\u0440\u0438\u043c\u0435\u0440\u043a\u0438:</b>\\n'' + ''<b>'' + $(''Parse Selected Dispenser'').first().json.name + ''</b>\\n\\n'' + ''\u2022 <b>\u0410\u0440\u0442\u0438\u043a\u0443\u043b:</b> <code>'' + $(''Parse Selected Dispenser'').first().json.sku + ''</code>\\n'' + ''\u2022 <b>\u0421\u0438\u0441\u0442\u0435\u043c\u0430:</b> <b>'' + $(''Parse Selected Dispenser'').first().json.system_code + ''</b>\\n'' + ''\u2022 <b>\u0426\u0432\u0435\u0442:</b> <b>'' + $(''Parse Selected Dispenser'').first().json.color_ru + ''</b>\\n\\n'' + ''\ud83d\udcf8 <b>\u0421\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 \u0448\u0430\u0433:</b> \u041e\u0442\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u0444\u043e\u0442\u043e \u0441\u0442\u0435\u043d\u044b \u0438\u043b\u0438 \u0441\u0430\u043d\u0443\u0437\u043b\u0430 \u043a\u043b\u0438\u0435\u043d\u0442\u0430 \u0432 \u044d\u0442\u043e\u0442 \u0447\u0430\u0442 \u0434\u043b\u044f \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438 \u0444\u043e\u0442\u043e\u043c\u043e\u043d\u0442\u0430\u0436\u0430.'' }}", "replyMarkup": "inlineKeyboard", "inlineKeyboard": {"rows": [{"row": {"buttons": [{"text": "\ud83d\udd04 \u0412\u044b\u0431\u0440\u0430\u0442\u044c \u0434\u0440\u0443\u0433\u043e\u0439 \u0434\u0438\u0441\u043f\u0435\u043d\u0441\u0435\u0440", "additionalFields": {"web_app": {"url": "={{ ($env.WEBHOOK_URL ? $env.WEBHOOK_URL.replace(/\\/+$/, '''') : ''http://localhost:8088'') + ''/app/index.html'' }}"}}}]}}]}, "additionalFields": {"appendAttribution": false, "parse_mode": "HTML"}}, "id": "node-send-dispenser-confirm", "name": "Send Dispenser Confirmation", "type": "n8n-nodes-base.telegram", "position": [420, 100], "typeVersion": 1.2, "credentials": {"telegramApi": {"id": "ASiKmvQz4bYnK32G", "name": "Telegram account"}}}, {"parameters": {"operation": "executeQuery", "query": "SELECT u.tg_user_id, COALESCE(u.selected_sku, ''551000'') as selected_sku, COALESCE(p.name, ''Tork Matic\u00ae \u0434\u0438\u0441\u043f\u0435\u043d\u0441\u0435\u0440 \u043f\u043e\u043b\u043e\u0442\u0435\u043d\u0435\u0446 H1'') as dispenser_name, COALESCE(p.system_code, ''H1'') as system_code, COALESCE(p.color, ''white'') as color, COALESCE(p.dimensions_cm, ''{\"w\": 33.7, \"h\": 37.2, \"d\": 20.6}''::jsonb) as dimensions_cm, COALESCE(p.category, ''dispenser'') as category FROM user_sessions_leads u LEFT JOIN products p ON p.sku = COALESCE(u.selected_sku, ''551000'') WHERE u.tg_user_id = {{ $(''Telegram Trigger'').first()?.json?.message ? $(''Telegram Trigger'').first()?.json?.message?.from?.id : ($(''Telegram Trigger'').first()?.json?.callback_query ? $(''Telegram Trigger'').first()?.json?.callback_query?.from?.id : $json.tg_user_id) }};", "options": {}}, "id": "node-fetch-manager-selection", "name": "Fetch Current Manager Selection (SQL)", "type": "n8n-nodes-base.postgres", "position": [200, 320], "typeVersion": 2.4, "credentials": {"postgres": {"id": "ssRaEX0w25vYf2wI", "name": "Postgres account"}}}, {"parameters": {"jsCode": "const fs = require(''fs'');\n\n// 1. Downloaded photo binary\nconst photoItem = $(''Download Telegram Photo'').first();\nlet userPhotoBase64 = '''';\nif (photoItem?.binary?.data?.data) {\n  userPhotoBase64 = photoItem.binary.data.data;\n}\n\n// 2. Selection from DB query\nconst selection = $(''Fetch Current Manager Selection (SQL)'').first()?.json || {};\nconst sku = String(selection.selected_sku || ''551000'').trim();\nconst name = selection.dispenser_name || ''\u0414\u0438\u0441\u043f\u0435\u043d\u0441\u0435\u0440 Tork'';\nconst systemCode = selection.system_code || ''H1'';\nconst color = selection.color || ''white'';\nconst dims = selection.dimensions_cm || { w: 33.7, h: 37.2, d: 20.6 };\n\n// 3. Load clean PNG from /data/assets/images/\nlet dispenserBase64 = '''';\nconst searchPaths = [\n  `/data/assets/images/${sku}.png`,\n  `/data/assets/images/${sku}.jpg`,\n  ''/data/assets/images/551000.png''\n];\n\nfor (const p of searchPaths) {\n  try {\n    if (fs.existsSync(p)) {\n      dispenserBase64 = fs.readFileSync(p).toString(''base64'');\n      if (dispenserBase64) break;\n    }\n  } catch (err) {}\n}\n\nconst promptText = `You are an expert AI photo editor for Tork (Essity). Mount and composite the exact Tork dispenser shown in the second image onto the washroom wall in the first image.\\n` +\n  `Location: mount the dispenser realistically on the wall near the sink or mirror at natural eye and hand reach level.\\n` +\n  `Preserve the exact product shape, color finish (${color}), front window, dispensing slot and Tork logo from the second reference image.\\n` +\n  `Real product dimensions: width ${dims.w || 33.7} cm, height ${dims.h || 37.2} cm.\\n` +\n  `Scale it realistically relative to the room tiles and counter. Cast natural realistic contact shadows onto the wall matching room lighting.\\n` +\n  `Return only the photorealistic composite image of the room with the mounted dispenser.`;\n\nconst tgTrigger = $(''Telegram Trigger'').first()?.json || {};\nconst fromUser = tgTrigger.message?.from || tgTrigger.callback_query?.from || {};\nconst tgUserId = fromUser.id || tgTrigger.message?.chat?.id || 0;\nconst chatId = tgTrigger.message?.chat?.id || tgTrigger.callback_query?.message?.chat?.id;\n\nreturn [{\n  json: {\n    sku: sku,\n    name: name,\n    system_code: systemCode,\n    color: color,\n    dimensions_cm: dims,\n    dimensions_w: dims.w || 33.7,\n    dimensions_h: dims.h || 37.2,\n    user_photo_base64: userPhotoBase64,\n    dispenser_clean_base64: dispenserBase64,\n    prompt_text: promptText,\n    tg_user_id: tgUserId,\n    chat_id: chatId\n  }\n}];"}, "id": "node-prepare-manager-montage", "name": "Prepare Manager Montage", "type": "n8n-nodes-base.code", "position": [420, 320], "typeVersion": 2}, {"parameters": {"jsCode": "const prep = $(''Prepare Manager Montage'').first()?.json || {};\nconst apiResponse = $input.first()?.json || {};\n\nlet base64Image = '''';\nlet mimeType = ''image/jpeg'';\nlet caption = '''';\n\nif (apiResponse.result_image_base64) {\n  base64Image = apiResponse.result_image_base64;\n  caption = apiResponse.caption;\n  mimeType = ''image/jpeg'';\n} else {\n  const parts = apiResponse.candidates?.[0]?.content?.parts || [];\n  const imagePart = parts.find(p => (p.inlineData && p.inlineData.data) || (p.inline_data && p.inline_data.data));\n\n  if (imagePart?.inlineData?.data) {\n    base64Image = imagePart.inlineData.data;\n    mimeType = imagePart.inlineData.mimeType || ''image/jpeg'';\n  } else if (imagePart?.inline_data?.data) {\n    base64Image = imagePart.inline_data.data;\n    mimeType = imagePart.inline_data.mime_type || ''image/jpeg'';\n  }\n}\n\n// Fallback to clean dispenser PNG if empty\nif (!base64Image) {\n  base64Image = prep.dispenser_clean_base64 || '''';\n  mimeType = ''image/png'';\n}\n\nif (!caption) {\n  const colorLabels = {\n    white: ''\u0411\u0435\u043b\u044b\u0439'',\n    black: ''\u0427\u0435\u0440\u043d\u044b\u0439'',\n    stainless_steel: ''\u041d\u0435\u0440\u0436\u0430\u0432\u0435\u044e\u0449\u0430\u044f \u0441\u0442\u0430\u043b\u044c'',\n    none: ''\u0421\u0442\u0430\u043d\u0434\u0430\u0440\u0442''\n  };\n  const colorRu = colorLabels[prep.color] || prep.color || ''\u0411\u0435\u043b\u044b\u0439'';\n\n  caption = `\u2728 <b>\u0412\u0438\u0437\u0443\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0433\u043e\u0442\u043e\u0432\u0430!</b>\\n\\n` +\n    `\u2022 \u0414\u0438\u0441\u043f\u0435\u043d\u0441\u0435\u0440: <b>${prep.name}</b>\\n` +\n    `\u2022 \u0410\u0440\u0442\u0438\u043a\u0443\u043b: <code>${prep.sku}</code>\\n` +\n    `\u2022 \u0421\u0438\u0441\u0442\u0435\u043c\u0430: <b>${prep.system_code}</b> (${colorRu})\\n` +\n    `\u2022 \u0413\u0430\u0431\u0430\u0440\u0438\u0442\u044b: ${prep.dimensions_w} \u00d7 ${prep.dimensions_h} \u0441\u043c\\n\\n` +\n    `<i>\u041c\u043e\u043d\u0442\u0430\u0436 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d \u0441 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435\u043c \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430 \u0438 \u0442\u0435\u043d\u0435\u0439.</i>`;\n}\n\nreturn [{\n  json: {\n    sku: prep.sku,\n    dispenser_name: prep.name,\n    system_code: prep.system_code,\n    caption: caption,\n    chat_id: prep.chat_id,\n    has_generated_image: Boolean(base64Image)\n  },\n  binary: {\n    visualization: {\n      data: base64Image,\n      mimeType: mimeType,\n      fileName: `tork_${prep.sku}_fitting.png`\n    }\n  }\n}];"}, "id": "node-process-manager-result", "name": "Process Manager Result", "type": "n8n-nodes-base.code", "position": [860, 320], "typeVersion": 2}, {"parameters": {"resource": "message", "operation": "sendPhoto", "chatId": "={{ $json.chat_id || $(''Telegram Trigger'').first().json.message.chat.id }}", "binaryData": true, "binaryPropertyName": "visualization", "caption": "={{ $json.caption }}", "replyMarkup": "inlineKeyboard", "inlineKeyboard": {"rows": [{"row": {"buttons": [{"text": "\ud83d\udd04 \u041f\u0440\u0438\u043c\u0435\u0440\u0438\u0442\u044c \u0434\u0440\u0443\u0433\u043e\u0439 \u0434\u0438\u0441\u043f\u0435\u043d\u0441\u0435\u0440", "additionalFields": {"web_app": {"url": "={{ ($env.WEBHOOK_URL ? $env.WEBHOOK_URL.replace(/\\/+$/, '''') : ''http://localhost:8088'') + ''/app/index.html'' }}"}}}]}}]}, "additionalFields": {"appendAttribution": false, "parse_mode": "HTML"}}, "id": "node-send-manager-result-photo", "name": "Send Manager Result Photo", "type": "n8n-nodes-base.telegram", "position": [1080, 320], "typeVersion": 1.2, "credentials": {"telegramApi": {"id": "ASiKmvQz4bYnK32G", "name": "Telegram account"}}}, {"parameters": {"chatId": "={{ $(''Check Manager Whitelist'').first()?.json?.auth?.chat_id || $json.tg_user_id || $(''Telegram Trigger'').first()?.json?.message?.chat?.id || $(''Telegram Trigger'').first()?.json?.callback_query?.message?.chat?.id }}", "text": "={{ ''\ud83d\udc4b <b>\u0417\u0434\u0440\u0430\u0432\u0441\u0442\u0432\u0443\u0439\u0442\u0435, '' + ($(''Check Manager Whitelist'').first()?.json?.auth?.user_name || $json.client_name || ''\u041c\u0435\u043d\u0435\u0434\u0436\u0435\u0440'') + ''!</b>\\n\\n'' + ''\u0414\u043e\u0431\u0440\u043e \u043f\u043e\u0436\u0430\u043b\u043e\u0432\u0430\u0442\u044c \u0432 <b>Tork Visualizer (Manager-Only Mode)</b>.\\n'' + ''\u042d\u0442\u043e\u0442 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442 \u043f\u0440\u0435\u0434\u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d \u0434\u043b\u044f \u0431\u044b\u0441\u0442\u0440\u043e\u0433\u043e \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u044f \u0444\u043e\u0442\u043e\u043c\u043e\u043d\u0442\u0430\u0436\u0430 \u0438 \u0432\u0438\u0437\u0443\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0434\u0438\u0441\u043f\u0435\u043d\u0441\u0435\u0440\u043e\u0432 Tork \u0432 \u0438\u043d\u0442\u0435\u0440\u044c\u0435\u0440\u0430\u0445 \u043a\u043b\u0438\u0435\u043d\u0442\u043e\u0432.\\n\\n'' + ''\ud83d\udce6 \u0412 \u043a\u0430\u0442\u0430\u043b\u043e\u0433\u0435 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e <b>165 \u0442\u043e\u0432\u0430\u0440\u043e\u0432 Tork</b> (83 \u043d\u0430\u0441\u0442\u0435\u043d\u043d\u044b\u0445 \u0434\u0438\u0441\u043f\u0435\u043d\u0441\u0435\u0440\u0430 \u0434\u043b\u044f \u043f\u0440\u0438\u043c\u0435\u0440\u043a\u0438).\\n\\n'' + ''\ud83d\ude80 <b>\u041a\u0430\u043a \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c:</b>\\n'' + ''1. \u041e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 <b>\u00ab\u2728 \u041a\u0430\u0442\u0430\u043b\u043e\u0433 \u0434\u0438\u0441\u043f\u0435\u043d\u0441\u0435\u0440\u043e\u0432\u00bb</b> \u043f\u043e \u043a\u043d\u043e\u043f\u043a\u0435 \u043d\u0438\u0436\u0435 \u0438 \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u043d\u0443\u0436\u043d\u044b\u0439 \u0430\u0440\u0442\u0438\u043a\u0443\u043b.\\n'' + ''2. \u041e\u0442\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u0432 \u044d\u0442\u043e\u0442 \u0447\u0430\u0442 \u0444\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0438\u044e \u0441\u0442\u0435\u043d\u044b \u0438\u043b\u0438 \u0441\u0430\u043d\u0443\u0437\u043b\u0430 \u043a\u043b\u0438\u0435\u043d\u0442\u0430.\\n'' + ''3. \u041d\u0435\u0439\u0440\u043e\u0441\u0435\u0442\u044c \u0441\u043c\u043e\u043d\u0442\u0438\u0440\u0443\u0435\u0442 \u0434\u0438\u0441\u043f\u0435\u043d\u0441\u0435\u0440 \u043d\u0430 \u0441\u0442\u0435\u043d\u0443 \u0441 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435\u043c \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430 \u0438 \u0435\u0441\u0442\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0442\u0435\u043d\u0435\u0439!'' }}", "replyMarkup": "inlineKeyboard", "inlineKeyboard": {"rows": [{"row": {"buttons": [{"text": "\u2728 \u041a\u0430\u0442\u0430\u043b\u043e\u0433 \u0434\u0438\u0441\u043f\u0435\u043d\u0441\u0435\u0440\u043e\u0432 (165 SKU)", "additionalFields": {"web_app": {"url": "={{ ($env.WEBHOOK_URL ? $env.WEBHOOK_URL.replace(/\\/+$/, '''') : ''http://localhost:8088'') + ''/app/index.html'' }}"}}}]}}]}, "additionalFields": {"appendAttribution": false, "parse_mode": "HTML"}}, "id": "node-send-manager-welcome", "name": "Send Manager Welcome & Menu", "type": "n8n-nodes-base.telegram", "position": [0, 500], "typeVersion": 1.2, "credentials": {"telegramApi": {"id": "ASiKmvQz4bYnK32G", "name": "Telegram account"}}}]', '{"Telegram Trigger": {"main": [[{"node": "Filter Private Chat Only", "type": "main", "index": 0}]]}, "Check Media Type": {"main": [[{"node": "Reject Video Message", "type": "main", "index": 0}], [{"node": "Upsert User Session", "type": "main", "index": 0}]]}, "Upsert User Session": {"main": [[{"node": "Route by Event Type", "type": "main", "index": 0}]]}, "Call Image Edit API": {"main": [[{"node": "Process Manager Result", "type": "main", "index": 0}]]}, "Route by Event Type": {"main": [[{"node": "Parse Selected Dispenser", "type": "main", "index": 0}], [{"node": "Download Telegram Photo", "type": "main"